var rs=UnityEngine.Object.FindObjectsByType<UnityEngine.Renderer>(UnityEngine.FindObjectsSortMode.None);var rows=new System.Collections.Generic.List<string>();foreach(var r in rs)if(r.gameObject.name=="WestPath_0"||r.gameObject.name=="WestPath_1"){var m=r.sharedMaterial;var mf=r.GetComponent<UnityEngine.MeshFilter>();var b=r.bounds;rows.Add(r.gameObject.name+";pos="+r.transform.position.ToString("R")+";scale="+r.transform.lossyScale.ToString("R")+";bounds="+b.size.ToString("R")+";mesh="+(mf&&mf.sharedMesh?mf.sharedMesh.name+":"+mf.sharedMesh.bounds.size.ToString("R"):"none")+";uv="+(m?m.GetTextureScale("_BaseMap").ToString("R"):"none"));}return string.Join("\n",rows);
